package org.solarelevation.alarm;
import android.content.*;
import java.io.*;
import java.util.*;
public final class SolarAlarmTiming {
public static final String SOURCE_ID="SolarAlarmTiming_v20261024T225906Z";
private static final long NTP_OFFSET=2208988800L;
private static volatile SolarAlarmTiming cached;
private static volatile String cachedKey="";
public static final class Sample {public final double jdUt1,jdTt,et,xp,yp,dut1;public final int leap;public final boolean extrapolated;Sample(double jdUt1,double jdTt,double et,double xp,double yp,double dut1,int leap,boolean extrapolated){this.jdUt1=jdUt1;this.jdTt=jdTt;this.et=et;this.xp=xp;this.yp=yp;this.dut1=dut1;this.leap=leap;this.extrapolated=extrapolated;}}
private static final class Eop {final double mjd,x,y,dut;Eop(double m,double x,double y,double d){mjd=m;this.x=x;this.y=y;dut=d;}}
private final Eop[] earth;
private final long[] leapTimes;
private final int[] leapOffsets;
private final long leapExpiry;
private SolarAlarmTiming(File eop,File leaps) throws IOException {earth=readEop(eop);TreeMap<Long,Integer> data=readLeap(leaps);leapExpiry=expiration(leaps);leapTimes=new long[data.size()];leapOffsets=new int[data.size()];int index=0;for(Map.Entry<Long,Integer> item:data.entrySet()){leapTimes[index]=item.getKey();leapOffsets[index]=item.getValue();index++;}}
private static double field(String line,int start,int end){return Double.parseDouble(line.substring(start,end).trim());}
private static Eop[] readEop(File file) throws IOException {ArrayList<Eop> rows=new ArrayList<>();try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(file),"US-ASCII"))){String s;while((s=reader.readLine())!=null){if(s.length()<68)continue;try{double m=field(s,7,15),x=field(s,18,27),y=field(s,37,46),d=field(s,58,68);if(!Double.isFinite(m)||!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(d)||m<30000||m>100000||Math.abs(x)>10||Math.abs(y)>10||Math.abs(d)>2)continue;if(!rows.isEmpty()&&m<=rows.get(rows.size()-1).mjd)continue;rows.add(new Eop(m,x,y,d));}catch(NumberFormatException|IndexOutOfBoundsException ignored){}}}if(rows.size()<30)throw new IOException("IERS finals2000A dataset contains too few valid daily records");return rows.toArray(new Eop[0]);}
private static long expiration(File file) throws IOException {try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(file),"US-ASCII"))){String s;while((s=reader.readLine())!=null){s=s.trim();if(s.startsWith("#@")){String[] words=s.split("\\s+");if(words.length>1)try{return Long.parseLong(words[1])-NTP_OFFSET;}catch(NumberFormatException ignored){}}}}return 0;}
private static TreeMap<Long,Integer> readLeap(File file) throws IOException {TreeMap<Long,Integer> entries=new TreeMap<>();try(BufferedReader reader=new BufferedReader(new InputStreamReader(new FileInputStream(file),"US-ASCII"))){String line;while((line=reader.readLine())!=null){String s=line.trim();if(s.isEmpty()||s.startsWith("#"))continue;String[] fields=s.split("\\s+");if(fields.length<2)continue;try{long ntp=Long.parseLong(fields[0]);int offset=Integer.parseInt(fields[1]);if(ntp<2208988800L||ntp>9000000000L||offset<0||offset>100)continue;entries.put(ntp-NTP_OFFSET,offset);}catch(NumberFormatException ignored){}}}if(entries.isEmpty())throw new IOException("NTP leap-seconds.list has no valid entries");return entries;}
public static void validate(String kind,File file) throws IOException {if(kind.equals(SolarAlarmDatasets.EOP)){readEop(file);return;}if(kind.equals(SolarAlarmDatasets.LEAP)){readLeap(file);return;}throw new IOException("Unsupported timing dataset");}
public static void invalidate(){cached=null;cachedKey="";}
public static synchronized SolarAlarmTiming get(Context c) throws IOException {if(!SolarAlarmDatasets.ready(c,SolarAlarmDatasets.EOP)||!SolarAlarmDatasets.ready(c,SolarAlarmDatasets.LEAP))throw new IOException("Load Earth orientation and leap seconds in Astronomical Data");SharedPreferences p=c.getSharedPreferences("astronomy_data",0);String key=p.getString("eop.sha256","")+":"+p.getString("leap.sha256","");if(cached==null||!cachedKey.equals(key)){cached=new SolarAlarmTiming(SolarAlarmDatasets.file(c,SolarAlarmDatasets.EOP),SolarAlarmDatasets.file(c,SolarAlarmDatasets.LEAP));cachedKey=key;}return cached;}
private Eop atMjd(double mjd){if(mjd<=earth[0].mjd)return earth[0];int last=earth.length-1;if(mjd>=earth[last].mjd)return earth[last];int lo=0,hi=last;while(hi-lo>1){int middle=(lo+hi)>>>1;if(earth[middle].mjd<=mjd)lo=middle;else hi=middle;}Eop a=earth[lo],b=earth[hi];double f=(mjd-a.mjd)/(b.mjd-a.mjd);return new Eop(mjd,a.x+(b.x-a.x)*f,a.y+(b.y-a.y)*f,a.dut+(b.dut-a.dut)*f);}
private int leapAt(long utc){long sec=Math.floorDiv(utc,1000L);int lo=0,hi=leapTimes.length;while(lo<hi){int middle=(lo+hi)>>>1;if(leapTimes[middle]<=sec)lo=middle+1;else hi=middle;}return leapOffsets[Math.max(0,lo-1)];}
public Sample at(long utc){double jdUtc=utc/86400000.0+2440587.5,mjd=jdUtc-2400000.5;Eop e=atMjd(mjd);int leap=leapAt(utc);double deltaT=leap+32.184;return new Sample(jdUtc+e.dut/86400.0,jdUtc+deltaT/86400.0,(utc/1000.0-946728000.0)+deltaT,e.x*Math.PI/(180*3600),e.y*Math.PI/(180*3600),e.dut,leap,mjd<earth[0].mjd||mjd>earth[earth.length-1].mjd||leapExpiry>0&&Math.floorDiv(utc,1000L)>leapExpiry);}
public static String diagnostics(Context c) throws IOException {SolarAlarmTiming t=get(c);Sample now=t.at(System.currentTimeMillis());StringBuilder out=new StringBuilder();out.append("EOP MJD range: ").append(t.earth[0].mjd).append(" to ").append(t.earth[t.earth.length-1].mjd).append('\n');out.append("Leap-second entry count: ").append(t.leapTimes.length).append('\n');out.append("Last leap-second effective Unix second: ").append(t.leapTimes[t.leapTimes.length-1]).append('\n');out.append("Leap-second list expiration Unix second: ").append(t.leapExpiry).append('\n');out.append("Leap-second list expired: ").append(t.leapExpiry>0&&System.currentTimeMillis()/1000L>t.leapExpiry).append('\n');out.append("Current TAI-UTC: ").append(now.leap).append(" seconds\n");out.append("Current UT1-UTC: ").append(now.dut1).append(" seconds\n");out.append("Current polar motion x/y radians: ").append(now.xp).append(" / ").append(now.yp).append('\n');out.append("EOP fallback: ").append(now.jdUt1-2400000.5<t.earth[0].mjd||now.jdUt1-2400000.5>t.earth[t.earth.length-1].mjd?"holding nearest supplied EOP value":"interpolated supplied values").append('\n');out.append("Leap-second policy: retain last supplied offset beyond final entry\n");return out.toString();}
private SolarAlarmTiming() throws IOException {throw new IOException("Dataset inputs required");}
}
